import React, { useState } from "react";
import styles from "./FormStyles.module.css";
import axios from "axios";

function Form() {
  const [name, setName] = useState("");
  const [img, setImg] = useState(null);
  const [role, setRole] = useState("");
  const [dob, setDob] = useState("");
  const [summary, setSummary] = useState("");
  const [skills, setSkills] = useState([""]);
  const [projects, setProjects] = useState([
    { name: "", description: "", technology: "" },
  ]);
  const [contact, setContact] = useState({
    email: "",
    phone: "",
    linkedIn: "",
    github: ""
  });

  const handleAddSkill = () => setSkills([...skills, ""]);
  const handleSkillChange = (index, value) => {
    const updatedSkills = [...skills];
    updatedSkills[index] = value;
    setSkills(updatedSkills);
  };
  const handleRemoveSkill = (index) =>
    setSkills(skills.filter((_, i) => i !== index));

  const handleAddProject = () =>
    setProjects([...projects, { name: "", description: "", technology: "" }]);
  const handleProjectChange = (index, field, value) => {
    const updatedProjects = [...projects];
    updatedProjects[index][field] = value;
    setProjects(updatedProjects);
  };
  const handleRemoveProject = (index) =>
    setProjects(projects.filter((_, i) => i !== index));

  const handleContactChange = (field, value) => {
    setContact({ ...contact, [field]: value });
  };

  const handleSubmit = (event) => {
    event.preventDefault();
  
    const formData = {
      name,
      img,
      role,
      dob,
      summary,
      skills,
      projects,
      contact,
    };
  
    axios.post('http://localhost:3001/submit-profile', formData)
      .then((result) => {
        console.log('Form submitted successfully:', result);
      })
      .catch((err) => {
        console.error('Form submission error:', err);
      });
    }

  return (
    <div className={styles.container}>
      <div className={styles.formContainer}>
        <form onSubmit={handleSubmit} className={styles.form}>
          <h2>PROFILE</h2>
          <input
            type="text"
            placeholder="Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />
          <input
            type="file"
            onChange={(e) => setImg(e.target.files[0])}
          />
          <input
            type="text"
            placeholder="Role"
            value={role}
            onChange={(e) => setRole(e.target.value)}
            required
          />
          <input 
            type="date" 
            value={dob} 
            onChange={(e) => setDob(e.target.value)} 
            required 
          />

          <h2>ABOUT SECTION</h2>
          <textarea
            placeholder="Professional Summary"
            value={summary}
            onChange={(e) => setSummary(e.target.value)}
          />

          {/* Skills Section */}
          <h2>Add Your Skills</h2>
          {skills.map((skill, index) => (
            <div key={index} className={styles.inputGroup}>
              <input
                type="text"
                value={skill}
                onChange={(e) => handleSkillChange(index, e.target.value)}
                placeholder={`Skill ${index + 1}`}
                className={styles.input}
              />
              <button
                type="button"
                onClick={() => handleRemoveSkill(index)}
                className={styles.remove}
              >
                Remove
              </button>
            </div>
          ))}
          <div className={styles.buttonGroup}>
            <button type="button" onClick={handleAddSkill}>
              Add Skill
            </button>
          </div>

          {/* Projects Section */}
          <h2>Add Your Projects</h2>
          {projects.map((project, index) => (
            <div key={index} className={styles.projectGroup}>
              <input
                type="text"
                value={project.name}
                onChange={(e) =>
                  handleProjectChange(index, "name", e.target.value)
                }
                placeholder={`Project Name ${index + 1}`}
                className={styles.input}
              />
              <textarea
                value={project.description}
                onChange={(e) =>
                  handleProjectChange(index, "description", e.target.value)
                }
                placeholder="Project Description"
                rows="3"
                className={styles.textarea}
              />
              <input
                type="text"
                value={project.technology}
                onChange={(e) =>
                  handleProjectChange(index, "technology", e.target.value)
                }
                placeholder="Technology Used"
                className={styles.input}
              />
              <button
                type="button"
                onClick={() => handleRemoveProject(index)}
                className={styles.remove}
              >
                Remove Project
              </button>
            </div>
          ))}
          <div className={styles.buttonGroup}>
            <button type="button" onClick={handleAddProject}>
              Add Project
            </button>
          </div>

          {/* Contact Section */}
          <h2>Contact Section</h2>
          <input
            type="email"
            placeholder="Email"
            value={contact.email}
            onChange={(e) =>
              handleContactChange("email", e.target.value)
            }
            required
          />
          <input
            type="number"
            placeholder="Phone Number"
            value={contact.phone}
            onChange={(e) => handleContactChange("phone", e.target.value)}
            required
          />
          <input
            type="url"
            name="linkedIn"
            placeholder="LinkedIn Link"
            pattern="https://.*"
            size="30"
            value={contact.linkedIn}
            onChange={(e) => handleContactChange("linkedIn", e.target.value)}
            required
          />
          <input
            type="url"
            name="github"
            placeholder="GitHub Link"
            pattern="https://.*"
            size="30"
            value={contact.github}
            onChange={(e) => handleContactChange("github", e.target.value)}
            required
          />
          <button type="submit">Submit</button>
        </form>
      </div>
    </div>
  );
}

export default Form;
